import json
from collections import Counter
from typing import Any

from fix_replay.collector import CollectResult
from fix_replay.parser import ParsedFiles
from shared.schemas import ExecutionReportEvent

# Fields that are stable across runs. order_id, exec_id and timestamps are
# regenerated by the pipeline on every run and are deliberately excluded.
_STABLE_FIELDS = (
    "exec_type",
    "symbol",
    "side",
    "price",
    "order_qty",
    "last_px",
    "last_qty",
    "reason",
)


def normalize(report: ExecutionReportEvent, client_prefix: str) -> dict[str, Any]:
    row: dict[str, Any] = {"client_id": report.client_id.removeprefix(client_prefix)}
    row.update({name: getattr(report, name) for name in _STABLE_FIELDS})
    return row


def _key(row: dict[str, Any]) -> str:
    return json.dumps(row, sort_keys=True)


def fingerprint(
    reports: list[ExecutionReportEvent], client_prefix: str
) -> list[dict[str, Any]]:
    """Sorted, ID-free view of a run. Sorted rather than arrival order because
    risk-service (New/Rejected) and matching-engine (Fill) produce to
    execution_reports independently, so their interleaving is not stable."""
    return sorted((normalize(r, client_prefix) for r in reports), key=_key)


def build_report(
    run_id: str,
    client_prefix: str,
    files: list[str],
    parsed: ParsedFiles,
    result: CollectResult,
) -> dict[str, Any]:
    by_type = Counter(r.exec_type for r in result.reports)
    reject_reasons = Counter(
        r.reason or "" for r in result.reports if r.exec_type == "8"
    )
    return {
        "run_id": run_id,
        "client_prefix": client_prefix,
        "files": files,
        "summary": {
            "orders_sent": len(parsed.orders),
            "session_messages_skipped": parsed.session_messages,
            "invalid_lines": len(parsed.invalid),
            "acks_received": result.acks,
            "timed_out": result.timed_out,
            "new": by_type["0"],
            "rejected": by_type["8"],
            "fills": by_type["F"],
            "filled_qty": sum(r.last_qty or 0 for r in result.reports),
            "reject_reasons": dict(sorted(reject_reasons.items())),
        },
        "invalid_lines": parsed.invalid,
        "executions": fingerprint(result.reports, client_prefix),
    }


def compare(baseline: dict[str, Any], current: dict[str, Any]) -> list[str]:
    """Multiset diff of the executions fingerprints. Empty means no regression."""
    expected = Counter(_key(r) for r in baseline["executions"])
    actual = Counter(_key(r) for r in current["executions"])
    lines = [f"- missing   x{n}: {k}" for k, n in sorted((expected - actual).items())]
    lines += [f"+ unexpected x{n}: {k}" for k, n in sorted((actual - expected).items())]
    return lines
